package com.aaliyun.leadnews.ai;
import com.aaliyun.leadnews.ai.client.AiModelClient;import com.aaliyun.leadnews.ai.config.*;import com.aaliyun.leadnews.ai.model.*;import com.aaliyun.leadnews.ai.service.*;import com.aaliyun.leadnews.ai.support.PromptCatalog;import com.aaliyun.leadnews.model.ai.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class ArticleModerationServiceTest {private ArticleAuditProperties props(){return new ArticleAuditProperties(5,20000,"leadnews",List.of("material/"),5242880,524288,2097152,3145728,1280,.8);}@Test void formalTextAuditUsesStructuredModel(){AiModelClient model=mock(AiModelClient.class);PromptCatalog prompts=mock(PromptCatalog.class);TrustedMediaLoader media=mock(TrustedMediaLoader.class);when(prompts.load("article-audit-system")).thenReturn("{format}");when(prompts.load("article-audit-user")).thenReturn("{title}|{labels}|{textContent}");var value=new ArticleAuditResult(ModerationDecision.PASS,RiskLevel.LOW,"safe",.9,List.of());when(model.structuredChatResult(anyString(),anyString(),eq(ArticleAuditResult.class))).thenReturn(new StructuredAiCallResult<>(value,"id",12,null));var service=new ArticleModerationService(model,prompts,media,props(),TestFixtures.properties(java.time.Duration.ofSeconds(1),1,2));var response=service.audit(new ArticleAuditRequest(1L,1,"title","label","text",List.of()));assertThat(response.result()).isEqualTo(value);assertThat(response.model()).isEqualTo("qwen3.8-max");verify(model).structuredChatResult(anyString(),contains("title|label|text"),eq(ArticleAuditResult.class));}
 @Test void formalImageAuditUsesTrustedBytes(){AiModelClient model=mock(AiModelClient.class);PromptCatalog prompts=mock(PromptCatalog.class);TrustedMediaLoader media=mock(TrustedMediaLoader.class);when(prompts.load(anyString())).thenReturn("{format}");var image=new AiImageInput("image/png",new byte[]{1},null);when(media.load(List.of("material/a.png"))).thenReturn(List.of(image));var value=new ArticleAuditResult(ModerationDecision.REVIEW,RiskLevel.MEDIUM,"review",.5,List.of("image"));when(model.structuredVision(anyString(),anyString(),anyList(),eq(ArticleAuditResult.class))).thenReturn(new StructuredAiCallResult<>(value,"id",20,null));var service=new ArticleModerationService(model,prompts,media,props(),TestFixtures.properties(java.time.Duration.ofSeconds(1),1,2));assertThat(service.audit(new ArticleAuditRequest(1L,1,"t",null,"x",List.of("material/a.png"))).result().decision()).isEqualTo(ModerationDecision.REVIEW);verify(media).load(List.of("material/a.png"));}
}
